module.exports = ({ name = "", dateBirth = "",  purpose= ""}) => {

  const generateRandomString = (length) => Array(length).fill('').reduce((result)=>{
    const characters = 'abcdefghijklmnopqrstuvwxyz0123456789';  
    const randomIndex = Math.floor(Math.random() * characters.length);
    return result += characters.charAt(randomIndex);  
  },'')

  const firstBigLetter = str => str.length ? str[0].toUpperCase()+str.slice(1).toLowerCase() : ''

  const fullName = (name.match(/[а-я]+/g) || []).map(el=>firstBigLetter(el))

  const fullYears = (ddmmyyyy) => Math.max(0, new Date(Date.now() - new Date(ddmmyyyy.split('.').reverse().join('-')).getTime()).getFullYear()-1970)

  
  return {
     id: generateRandomString(10),
     firstName: fullName[0] || '', 
     lastName: fullName[1] || '', 
     dateBirth: dateBirth,
     age: fullYears(dateBirth),
     purpose: firstBigLetter(purpose)
  }

}

